  &reftitle.parameters;




     expressions


output गरिने एक वा बढी string expressions, जसलाई अल्पविराम (comma) ले छुट्याइन्छ।  strict_types directive enable गरिएको भए पनि string नभएका values लाई strings मा coerce गरिनेछ।

  &reftitle.examples;



    echo का उदाहरणहरू


<?php
echo "echo does not require parentheses.";

// Strings can either be passed individually as multiple arguments or
// concatenated together and passed as a single argument
echo 'This ', 'string ', 'was ', 'made ', 'with multiple parameters.', "\n";
echo 'This ' . 'string ' . 'was ' . 'made ' . 'with concatenation.' . "\n";

// No newline or space is added; the below outputs "helloworld" all on one line
echo "hello";
echo "world";

// Same as above
echo "hello", "world";

echo "This string spans
multiple lines. The newlines will be
output as well";

echo "This string spans\nmultiple lines. The newlines will be\noutput as well.";

// The argument can be any expression which produces a string
$foo = "example";
echo "foo is $foo"; // foo is example

$fruits = ["lemon", "orange", "banana"];
echo implode(" and ", $fruits); // lemon and orange and banana

// Non-string expressions are coerced to string, even if declare(strict_types=1) is used
echo 6 * 7; // 42

// However, the following examples will work:
($some_var) ? print 'true' : print 'false'; // print is also a construct, but
                                            // it is a valid expression, returning 1,
                                            // so it may be used in this context.

echo $some_var ? 'true': 'false'; // evaluating the expression first and passing it to echo
?>







    echo एउटा expression होइन


<?php
// Because echo does not behave as an expression, the following code is invalid.
($some_var) ? echo 'true' : echo 'false';
?>

  &reftitle.notes;
  &note.language-construct;


   parentheses सँगको प्रयोग

echo मा एउटा मात्र argument लाई parentheses भित्र राख्दा कुनै syntax error आउँदैन, र यसले सामान्य function call जस्तो देखिने syntax बनाउँछ। तर, यो भ्रमपूर्ण हुन सक्छ, किनभने ती parentheses वास्तवमा output भइरहेको expression कै भाग हुन्, echo syntax आफैँको भाग होइनन्।
     Parentheses को प्रयोग


<?php
echo "hello", PHP_EOL;
// outputs "hello"

echo("hello"), PHP_EOL;
// also outputs "hello", because ("hello") is a valid expression

echo(1 + 2) * 3, PHP_EOL;
// outputs "9"; the parentheses cause 1+2 to be evaluated first, then 3*3
// the echo statement sees the whole expression as one argument

echo "hello", " world", PHP_EOL;
// outputs "hello world"

echo("hello"), (" world"), PHP_EOL;
// outputs "hello world"; the parentheses are part of each expression
?>








     अमान्य Expression


<?php
echo("hello", " world"), PHP_EOL;
// Throws a Parse Error because ("hello", " world") is not a valid expression
?>








echo मा multiple arguments pass गर्नाले PHP मा concatenation operator को precedence from आउने जटिलताहरूबाट बच्न सकिन्छ। instance को लागि, concatenation operator को precedence ternary operator भन्दा उच्च हुन्छ, र PHP भन्दा पहिले 8.0.0 को precedence addition र subtraction सरह थियो:


<?php
// Below, the expression 'Hello ' . isset($name) is evaluated first,
// and is always true, so the argument to echo is always $name
echo 'Hello ' . isset($name) ? $name : 'John Doe' . '!';

// The intended behaviour requires additional parentheses
echo 'Hello ' . (isset($name) ? $name : 'John Doe') . '!';

// In PHP prior to 8.0.0, the below outputs "2", rather than "Sum: 3"
echo 'Sum: ' . 1 + 2;

// Again, adding parentheses ensures the intended order of evaluation
echo 'Sum: ' . (1 + 2);



यदि धेरै वटा arguments pass गरिएका छन् भने, precedence लागू गर्न parentheses आवश्यक पर्दैन, किनभने each expression छुट्टै हुन्छ:


<?php
echo "Hello ", isset($name) ? $name : "John Doe", "!";

echo "Sum: ", 1 + 2;
